"use strict";(globalThis.webpackChunkgrc||=[]).push([[95751],{48625(e){e.exports=JSON.parse('{"citeKey":"cernuda2024hstream","slug":"cernuda-2024-hstream-3043","title":"HStream: A hierarchical data streaming engine for high-throughput scientific applications","authors":["J. Cernuda","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 53th International Conference on Parallel Processing (ICPP\'24)","type":"Conference","entryType":"inproceedings","date":"August, 2024","year":2024,"era":"iit","month":8,"doi":"10.1145/3673038.3673150","abstract":"Data streaming is gaining traction in high-performance computing (HPC) as a mechanism for continuous data transfer, but remains underutilized as a processing paradigm due to the inadequacy of existing technologies, which are primarily designed for cloud archi- tectures and ill-equipped to tackle HPC-specific challenges. This work introduces HStream, a novel data management design for out-of-core data streaming engines. Central to the HStream design is the separation of data and computing planes at the task level. By managing them independently, issues such as memory thrashing and back-pressure, caused by the high volume, velocity, and bursti- ness of I/O in HPC environments, can be effectively addressed at runtime. Specifically, HStream utilizes adaptive parallelism and hi- erarchical memory management, enabled by this design paradigm, to alleviate memory pressure and enhance system performance. These improvements enable HStream to match the performance of state-of-the-art HPC streaming engines and achieve up to a 1.5x reduction in latency under high data loads.","hasAbstract":true,"lede":"Data streaming is gaining traction in high-performance computing (HPC) as a mechanism for continuous data transfer.","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-hstream-3043.pdf"},"tags":["Data Streaming","HPC","Hierarchical Storage","Elastic System","In-Transit Computing","LABIOS"],"_projectIds":["chronolog","labios","coeus","dtio"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["iowarp","coeus","labios","dtio","chronolog","hermes"],"memberAuthors":["cernuda-jaime","ye-jie","kougkas-anthony","sun-xian-he"],"funding":[{"agency":"NSF","award":"OAC-2104013","projectId":"chronolog"},{"agency":"NSF","award":"OAC-2313154","projectId":"labios"},{"agency":"DOE","award":"DE-SC0023263","projectId":"coeus"},{"agency":"DOE","award":"DE-SC0024593","projectId":"dtio"}]}')}}]);